// ServerInterface represents all server handlers.
type ServerInterface interface {
	// GetLivez Report that the process is running
	// (GET /livez)
	GetLivez(w http.ResponseWriter, r *http.Request)
	// GetReadyz Report whether the server can take traffic
	// (GET /readyz)
	GetReadyz(w http.ResponseWriter, r *http.Request)
	// DeleteMe Delete the signed-in person's account
	// (DELETE /v1/me)
	DeleteMe(w http.ResponseWriter, r *http.Request)
	// GetMe Get the signed-in person, their teams and what they may do in each
	// (GET /v1/me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// UpdateMe Change the signed-in person's name
	// (PATCH /v1/me)
	UpdateMe(w http.ResponseWriter, r *http.Request)
	// GetVersion Report the server's build version
	// (GET /v1/version)
	GetVersion(w http.ResponseWriter, r *http.Request)
}

// ServerInterfaceWrapper converts contexts to parameters.
type ServerInterfaceWrapper struct {
	Handler            ServerInterface
	HandlerMiddlewares []MiddlewareFunc
	ErrorHandlerFunc   func(w http.ResponseWriter, r *http.Request, err error)
}

type MiddlewareFunc func(http.Handler) http.Handler

// GetLivez operation middleware
func (siw *ServerInterfaceWrapper) GetLivez(w http.ResponseWriter, r *http.Request) {

	handler := http.Handler(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		siw.Handler.GetLivez(w, r)
	}))

	for _, middleware := range siw.HandlerMiddlewares {
		handler = middleware(handler)
	}

	handler.ServeHTTP(w, r)
}

